21	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
22	            throws MissingOwnerFieldsException {
23	        List<String> missing = new ArrayList<>();
24	        requireText("firstName", request.getFirstName(), missing);
25	        requireText("lastName", request.getLastName(), missing);
26	        requireAddress(request.getAddress(), missing);
27	        requireText("city", request.getCity(), missing);
28	        requireText("telephone", request.getTelephone(), missing);
29	        if (!missing.isEmpty()) {
30	            throw new MissingOwnerFieldsException(missing);
