121	
122	    /**
123	     * A pragmatic syntactic check: a non-empty local part, a single {@code @}, and a domain with at
124	     * least one dot-separated label ending in a letters-only top-level label of length 2+.
125	     */
126	    private static final Pattern EMAIL = Pattern.compile(
127	            "^[A-Za-z0-9!#$%&'*+/=?^_`{|}~.-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}$");
