132	            request.setEmail(null);
133	            return;
134	        }
135	        String trimmed = email.trim();
136	        if (!EMAIL.matcher(trimmed).matches()) {
137	            throw new InvalidEmailException(email);
138	        }
139	        request.setEmail(trimmed.toLowerCase());
