203	import net.officefloor.plugin.variable.Val;
204	import org.springframework.samples.petclinic.mapper.Locality;
205	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
206	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
207	
208	/**
209	 * Step of {@code POST /api/owners}: validates the optional {@code postcode} WHEN PRESENT. A
210	 * supplied postcode must be four digits and, for a city with a known region (derived through
211	 * {@link Locality}: Sydney&rarr;NSW, Melbourne&rarr;VIC, Brisbane&rarr;QLD), fall inside that
212	 * region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
213	 * region accepts any 4-digit postcode. An absent postcode is left untouched, so the request
214	 * contract stays backward-compatible; anything invalid is rejected 400 via
215	 * {@link InvalidPostcodeException}.
216	 */
217	public class RequirePostcode {
218	
219	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
220	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
221	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
222	
223	    public void service(@Val OwnerFieldsDto request) throws InvalidPostcodeException {
224	        String postcode = request.getPostcode();
225	        if (postcode == null || postcode.isBlank()) {
226	            return; // optional when absent
227	        }
228	        if (!postcode.matches("[0-9]{4}")) {
229	            throw new InvalidPostcodeException(postcode);
230	        }
231	        int[] range = REGION_POSTCODES.get(Locality.of(request.getCity()));
232	        if (range != null) {
233	            int value = Integer.parseInt(postcode);
234	            if (value < range[0] || value > range[1]) {
235	                throw new InvalidPostcodeException(postcode);
236	            }
237	        }
238	    }
