241	package org.springframework.samples.petclinic.rest.function.owner;
242	
243	import net.officefloor.plugin.variable.Val;
244	import org.springframework.samples.petclinic.model.Owner;
245	import org.springframework.samples.petclinic.repository.OwnerRepository;
246	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
247	import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;
248	
249	/**
250	 * Duplicate-detection step of {@code POST /api/owners}: rejects the request 409 when the new owner
251	 * duplicates an existing one. Because the {@code householdId} is now deterministic &mdash; derived
252	 * from the last name and postcode (see {@link OwnerIdentity#householdId(String, String)}) &mdash;
253	 * two owners sharing a last name and postcode belong to the <em>same</em> household, and a second
254	 * such owner is a household duplicate.
255	 *
256	 * <p>Two independent conflicts are checked against every existing owner:
257	 * <ul>
258	 * <li><b>Exact identity</b>: the whole {@code identityKey}
259	 *   ({@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty)}) matches.
260	 *   This always conflicts &mdash; a genuinely identical record is never allowed.</li>
261	 * <li><b>Household duplicate</b>: the computed {@code householdId} matches, i.e. the same last name
262	 *   and postcode. This is rejected <em>unless</em> the request opts in with
263	 *   {@code sharesHousehold: true}, in which case the new owner is admitted as a declared member of
264	 *   the household.</li>
265	 * </ul>
266	 *
267	 * <p>Runs after the normalize steps (so telephone is E.164 and email lower-cased) and before
268	 * {@link BuildOwner}, so no owner is persisted on conflict. The {@code householdId} is derived
269	 * exactly as {@link AssignHouseholdId} will later stamp it.
270	 */
271	public class RequireUniqueIdentity {
272	
273	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
274	            throws DuplicateIdentityException {
275	        String householdId = OwnerIdentity.householdId(request.getLastName(), request.getPostcode());
276	        boolean sharesHousehold = Boolean.TRUE.equals(request.getSharesHousehold());
277	        String identityKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(), householdId);
278	        for (Owner existing : ownerRepository.findAll()) {
279	            String existingKey = OwnerIdentity.key(existing.getTelephone(), existing.getEmail(),
280	                    existing.getHouseholdId());
281	            if (identityKey.equals(existingKey)) {
282	                throw new DuplicateIdentityException(identityKey);
283	            }
284	            if (!sharesHousehold && householdId != null
285	                    && householdId.equals(existing.getHouseholdId())) {
286	                throw new DuplicateIdentityException(householdId);
287	            }
288	        }
289	    }
290	}
