556	 * (the earliest-created match when there is more than one). Otherwise {@code possibleDuplicate} is
557	 * set false and {@code possibleDuplicateOf} left null.
558	 *
559	 * <p>A <em>declared</em> household member &mdash; one that opted in with {@code sharesHousehold} to
560	 * join an existing household (same last name and postcode) rather than be rejected as a household
561	 * duplicate &mdash; is never a suspected duplicate: its shared last name and postcode are exactly
562	 * what it declared, so it is left unflagged.
563	 *
564	 * <p>Runs after {@link BuildOwner} (so it can mutate the built owner in place) and before
565	 * {@link SaveOwner}, under the write transaction. A new owner with no postcode never soft-matches.
566	 */
567	public class FlagPossibleDuplicate {
568	
569	    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
570	        owner.setPossibleDuplicate(false);
571	        owner.setPossibleDuplicateOf(null);
572	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
573	            return; // a declared household member is not a suspected duplicate
574	        }
575	        String postcode = owner.getPostcode();
576	        if (postcode == null || postcode.isBlank()) {
577	            return;
578	        }
579	        String lastName = normalize(owner.getLastName());
580	        String telephone = owner.getTelephone();
581	        Owner match = null;
582	        for (Owner existing : ownerRepository.findAll()) {
583	            if (!lastName.equals(normalize(existing.getLastName()))
584	                    || !postcode.equals(existing.getPostcode())) {
585	                continue;
586	            }
587	            if (telephone != null && telephone.equals(existing.getTelephone())) {
588	                continue; // same telephone is not a soft match
589	            }
590	            if (match == null || existing.getId() < match.getId()) {
591	                match = existing;
592	            }
593	        }
594	        if (match != null) {
595	            owner.setPossibleDuplicate(true);
596	            owner.setPossibleDuplicateOf(match.getId());
597	        }
598	    }
599	
600	    private static String normalize(String value) {
601	        return value == null ? "" : value.trim().toLowerCase(Locale.ROOT);
602	    }
603	}
