663	package org.springframework.samples.petclinic.rest.function.owner;
664	
665	import java.util.Locale;
666	
667	/**
668	 * Normalises a free-text owner {@code address} to a single canonical form.
669	 *
670	 * <p>Whitespace is trimmed and internal runs collapse to a single space, the text is upper-cased,
671	 * and common street-type abbreviations are expanded on whole tokens ({@code ST -> STREET},
672	 * {@code RD -> ROAD}, {@code AVE -> AVENUE}). So {@code "  12  main  st "} becomes
673	 * {@code "12 MAIN STREET"}. A {@code null} or whitespace-only value normalises to the empty string.
674	 */
675	final class AddressNormalizer {
676	
677	    private AddressNormalizer() {
678	    }
679	
680	    /**
681	     * Returns the canonical form of {@code raw}, or {@code ""} when it is {@code null} or blank once
682	     * whitespace is trimmed. The result is idempotent: normalising an already-normalised address
683	     * returns it unchanged.
684	     */
685	    static String normalize(String raw) {
686	        if (raw == null) {
687	            return "";
688	        }
689	        String cleaned = raw.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
690	        if (cleaned.isEmpty()) {
691	            return "";
692	        }
693	        String[] tokens = cleaned.split(" ");
694	        StringBuilder sb = new StringBuilder(cleaned.length());
695	        for (int i = 0; i < tokens.length; i++) {
696	            if (i > 0) {
697	                sb.append(' ');
698	            }
699	            sb.append(expand(tokens[i]));
700	        }
701	        return sb.toString();
702	    }
703	
704	    /** Expands a single upper-cased token if it is a known street-type abbreviation. */
705	    private static String expand(String token) {
706	        switch (token) {
707	            case "ST":
708	                return "STREET";
709	            case "RD":
710	                return "ROAD";
711	            case "AVE":
712	                return "AVENUE";
713	            default:
714	                return token;
715	        }
716	    }
717	}
