719	package org.springframework.samples.petclinic.rest.function.owner;
720	
721	import java.util.LinkedHashMap;
722	import java.util.Map;
723	
724	/**
725	 * Normalises telephone numbers to <a href="https://en.wikipedia.org/wiki/E.164">E.164</a> form.
726	 *
727	 * <p>Spaces, dashes and brackets are stripped. A leading {@code '+'} and its country code are kept
728	 * as given; otherwise country code {@code +61} is assumed and a single leading {@code '0'} is
729	 * dropped from the national digits. The result is a {@code '+'} followed by 8 to 15 digits, so
730	 * {@code "0412 345 678"} becomes {@code "+61412345678"}.
731	 *
732	 * <p>For known country codes the national-number length is checked as well: {@code +61} requires 9
733	 * national digits and {@code +1} requires 10. A number whose national part is the wrong length for
734	 * its country is rejected (returns {@code null}).
735	 */
736	final class E164Telephone {
737	
738	    /**
739	     * Country code (without the {@code '+'}) to its required national-number length. Ordered
740	     * longest-prefix first so a {@code +61} number is matched by {@code "61"} before {@code "1"}.
741	     */
742	    private static final Map<String, Integer> NATIONAL_LENGTH = new LinkedHashMap<>();
743	
744	    static {
745	        NATIONAL_LENGTH.put("61", 9);
746	        NATIONAL_LENGTH.put("1", 10);
747	    }
748	
749	    private E164Telephone() {
750	    }
751	
752	    /**
753	     * Returns the E.164 form of {@code raw}, or {@code null} when it cannot form a valid E.164
754	     * number: non-digit content after stripping separators, not 8 to 15 digits after the
755	     * {@code '+'}, or the wrong national-number length for a known country code ({@code +61} needs 9
756	     * national digits, {@code +1} needs 10).
757	     */
758	    static String normalize(String raw) {
759	        if (raw == null) {
760	            return null;
761	        }
762	        // Strip spaces, dashes and brackets.
763	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
764	        String digits;
765	        if (cleaned.startsWith("+")) {
766	            // Keep the leading '+' and country code as given.
767	            digits = cleaned.substring(1);
768	        }
769	        else {
770	            // No country code: assume '+61' and drop a single leading '0' from the national digits.
771	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
772	            digits = "61" + national;
773	        }
774	        if (!digits.matches("\\d{8,15}")) {
775	            return null;
776	        }
777	        // Enforce the national-number length for recognised country codes.
778	        for (Map.Entry<String, Integer> country : NATIONAL_LENGTH.entrySet()) {
779	            String code = country.getKey();
780	            if (digits.startsWith(code)) {
781	                if (digits.length() - code.length() != country.getValue()) {
782	                    return null;
783	                }
784	                break;
785	            }
786	        }
787	        return "+" + digits;
788	    }
789	}
