791	package org.springframework.samples.petclinic.rest.function.owner;
792	
793	import java.nio.charset.StandardCharsets;
794	import java.security.MessageDigest;
795	import java.security.NoSuchAlgorithmException;
796	import java.util.Locale;
797	
798	/**
799	 * Derives an owner's {@code identityKey} &mdash; the single value all duplicate detection is now
800	 * expressed through.
801	 *
802	 * <p>The key is {@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty)}.
803	 * Two owners are duplicates only when their <em>whole</em> keys are equal: because the telephone is
804	 * part of the key, two members of the same household (same {@code householdId}) with different
805	 * telephones have different keys and are both allowed.
806	 */
807	public final class OwnerIdentity {
808	
809	    private OwnerIdentity() {
810	    }
811	
812	    /**
813	     * Builds the identity key from an owner's parts. The telephone is expected to already be in
814	     * E.164 form (as stored); the email is compared lower-cased and a null/blank email or
815	     * {@code householdId} contributes an empty segment.
816	     */
817	    public static String key(String telephone, String email, String householdId) {
818	        String tel = telephone == null ? "" : telephone;
819	        String em = (email == null || email.isBlank()) ? "" : email.trim().toLowerCase(Locale.ROOT);
820	        String hh = householdId == null ? "" : householdId;
821	        return tel + "|" + em + "|" + hh;
822	    }
823	
824	    /**
825	     * The hash segment of an owner's {@code '<REGION>-<HASH8>'} customer code: the first 8
826	     * upper-case hex characters of SHA-256 over the normalised telephone concatenated with the
827	     * last name. The telephone is expected to already be in E.164 form (as stored).
828	     */
829	    public static String customerHash(String normalizedTelephone, String lastName) {
830	        String tel = normalizedTelephone == null ? "" : normalizedTelephone;
831	        String last = lastName == null ? "" : lastName;
832	        try {
833	            byte[] digest = MessageDigest.getInstance("SHA-256")
834	                .digest((tel + last).getBytes(StandardCharsets.UTF_8));
835	            StringBuilder sb = new StringBuilder(8);
836	            for (int i = 0; i < 4; i++) {
837	                sb.append(String.format("%02X", digest[i]));
838	            }
839	            return sb.toString();
840	        }
841	        catch (NoSuchAlgorithmException ex) {
842	            throw new IllegalStateException(ex);
843	        }
844	    }
845	
846	    /**
847	     * The household's stable, deterministic identifier: the first 12 upper-case hex characters of
848	     * SHA-256 over {@code normalizedLastName + '|' + postcode}. Owners sharing a last name and
849	     * postcode therefore resolve to the same value automatically, regardless of creation order or
850	     * whether they opted into {@code sharesHousehold}. Returns {@code null} when no postcode is
851	     * given, since a household is keyed on (last name, postcode) and cannot form without one.
852	     */
853	    public static String householdId(String lastName, String postcode) {
854	        if (postcode == null || postcode.isBlank()) {
855	            return null;
856	        }
857	        try {
858	            String key = normalizeName(lastName) + "|" + postcode;
859	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
860	            StringBuilder sb = new StringBuilder(12);
861	            for (int i = 0; i < 6; i++) {
862	                sb.append(String.format("%02X", digest[i]));
863	            }
864	            return sb.toString();
865	        }
866	        catch (NoSuchAlgorithmException ex) {
867	            throw new IllegalStateException(ex);
868	        }
869	    }
870	
871	    /** Lower-case, trim, and collapse internal whitespace runs to a single space. */
872	    static String normalizeName(String value) {
873	        if (value == null) {
874	            return "";
875	        }
876	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
877	    }
878	}
