880	package org.springframework.samples.petclinic.rest.function.owner;
881	
882	import java.time.DayOfWeek;
883	import java.time.LocalDate;
884	
885	/**
886	 * Resolves the effective registration date for a new owner. The date is the one supplied in the
887	 * request when present, otherwise the server's current date; either way it must fall on a business
888	 * day, so a Saturday or Sunday is rolled forward to the following Monday.
889	 *
890	 * <p>Shared by {@link ApplyRegistrationDate} (which stores it on the owner and thereby feeds every
891	 * value derived from it, such as the membership number's year segment) and
892	 * {@link RequireDailyCapacity} (which counts owners per adjusted business day).
893	 */
894	final class RegistrationDate {
895	
896	    private RegistrationDate() {
897	    }
898	
899	    /**
900	     * The effective registration date: {@code supplied} when non-null, otherwise today, rolled
901	     * forward to the next business day.
902	     */
903	    static LocalDate effective(LocalDate supplied) {
904	        return toBusinessDay(supplied != null ? supplied : LocalDate.now());
905	    }
906	
907	    /** Roll a weekend date forward to the following Monday; a weekday is returned unchanged. */
908	    static LocalDate toBusinessDay(LocalDate date) {
909	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
910	            date = date.plusDays(1);
911	        }
912	        return date;
913	    }
914	}
